pub fn dump_LigatureSet2(
    out: &mut impl Write,
    path: &str,
    value: &LigatureSet2<'_>,
) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::visit(out, path, 600464183, value.offset_data().len(), dump_args)? {
        return Ok(());
    }
    let base = value.offset_data();
    {
        let path = &format!("{path}.ligatureCount");
        let fieldValue = value.ligature_count();
        writeln!(out, "{path}={}", fieldValue)?;
    }
    {
        let path = &format!("{path}.ligatureOffsets");
        let fieldValue = value.ligature_offsets();
        writeln!(out, "{path}.length={}", fieldValue.len())?;
        for (index, item) in fieldValue.iter().enumerate() {
            let path = &format!("{path}[{index}]");
            let item = item.get();
            writeln!(out, "{path}={}", item.to_u32())?;
        }
    }
    {
        let path = &format!("{path}.ligatures");
        let target_args: [u64; 3] = [0, 0, 0];
        let resolvedArray = value.ligatures();
        writeln!(out, "{path}.length={}", resolvedArray.len())?;
        for index in 0..resolvedArray.len() {
            let path = &format!("{path}[{index}]");
            crate::dump_support::set_arguments(target_args);
            let resolved = resolvedArray.get(index);
            match resolved {
                Ok(table) => table.dump(out, path)?,
                Err(error) => writeln!(out, "{path}.error={}", crate::error(error))?,
            }
        }
    }
    Ok(())
}

